/// <summary>
/// calling the report
/// </summary>
/// <param name = "_args">Arguments</param>
public static void main(Args _args)
{
    METVendAccruedPurchasesController controller = new METVendAccruedPurchasesController();
    controller.parmReportName(ssrsReportStr(METVendAccruedPurchases, Report));
    controller.parmArgs(_args);
    controller.startOperation();
}
